json; conn = sqlite3.connect('world.db'); c = conn.cursor(); tables = [r[0] for r in c.execute(\"SELECT name FROM sqlite_master WHERE type='table'\").fetchall()]; result = {}; 
for t in tables:
    cols = [(r[1],r[2]) for r in c.execute(f'PRAGMA table_info({t})').fetchall()]
    result[t] = cols
print(json.dumps(result, indent=2))\

